<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\UserInvitationRolesVO;

trait UserInvitationRolesAccessor
{
    private ?UserInvitationRolesVO $_roles = null;
    public function getRoles(): ?string
    {
        return $this->_roles?->value();
    }
    public function roles(): ?UserInvitationRolesVO
    {
        return $this->_roles;
    }
    public function isRolesChanged(?self $original = null): bool
    {
        return null !== $this->_roles && !$this->_roles->equals($original?->_roles);
    }
    public function withRoles(UserInvitationRolesVO|string|null $roles): self
    {
        $copy = clone $this;
        $copy->_roles = UserInvitationRolesVO::from($roles);
        return $copy;
    }
}
